import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, Vector3 } = THREE;

  const group = new Group();

  // Atlas source rect
  const srcX = 0;
  const srcY = 0;
  const srcW = 512;
  const srcH = 320;
  const aspect = srcW / srcH;

  // Size the plane to the atlas region aspect ratio
  const planeWidth = 1.6;
  const planeHeight = planeWidth / aspect;

  const geo = new PlaneGeometry(planeWidth, planeHeight);

  const mat = new MeshBasicNodeMaterial({
    transparent: true,
    side: THREE.DoubleSide,
    depthWrite: false,
    toneMapped: true,
  });

  const mesh = new Mesh(geo, mat);
  mesh.renderOrder = 5;
  group.add(mesh);

  // --- Billboard toward camera every frame ---
  const camPos = new Vector3();
  mesh.onBeforeRender = (_renderer, _scene, camera) => {
    camera.getWorldPosition(camPos);
    mesh.lookAt(camPos);
  };

  // --- Load texture and apply atlas UV offset ---
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.minFilter = THREE.LinearFilter;
      tex.magFilter = THREE.LinearFilter;
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.generateMipmaps = false;

      const atlasW = tex.image?.width || srcW;
      const atlasH = tex.image?.height || srcH;

      // Source rect is in top-left image coords; Three.js flipY=true by default
      tex.offset.set(
        srcX / atlasW,
        1 - (srcY + srcH) / atlasH
      );
      tex.repeat.set(
        srcW / atlasW,
        srcH / atlasH
      );

      mat.map = tex;
      mat.needsUpdate = true;
    });
  }

  // --- Subtle idle floating (breathing <=2%, sine drift) ---
  const floatTL = gsap.timeline({ repeat: -1, yoyo: true });
  floatTL.to(mesh.position, {
    y: 0.05,
    duration: 2.8,
    ease: 'sine.inOut',
  });
  floatTL.to(mesh.position, {
    y: -0.04,
    duration: 2.2,
    ease: 'sine.inOut',
  }, 0);

  // --- Handlers (none — static composition, no interactivity) ---
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    floatTL.kill();
    geo.dispose();
    if (mat.map) mat.map.dispose();
    mat.dispose();
    mesh.onBeforeRender = null;
  };

  return group;
}
